/* Build-time Markdown HTML is bundled with data.js, including for offline reading. */
window.createKnowledgeArticles=({data,href,e,icon})=>{
 const all=data.articles||[], groups=['前端部分','后端部分','运行时部分'];
 const route=(a,section='')=>href({view:'articles',domain:a.domain,article:a.id,section});
 const card=a=>`<a class="article-card" href="${route(a)}"><span class="article-order">${String(a.order).padStart(2,'0')}</span><div><h3>${e(a.title)}</h3><p>${e(a.summary)}</p><span class="article-card-meta">原图 ${e(a.printedPages)} 页 · ${a.toc.length} 个小节</span></div>${icon('arrow')}</a>`;
 function render(state){
  const chapters=all.filter(a=>a.domain===state.domain),current=chapters.find(a=>a.id===state.article),pageCount=new Set(chapters.flatMap(a=>a.photos)).size,figureCount=new Set(chapters.flatMap(a=>a.assets)).size;
  if(!current){
   const tokens=state.q.trim().toLowerCase().split(/\s+/).filter(Boolean);
   const matches=chapters.filter(a=>tokens.every(t=>(a.title+' '+a.text).normalize('NFKC').toLowerCase().includes(t.normalize('NFKC'))));
   return `<header class="article-library-head"><span class="eyebrow">编译原理知识地图 · Markdown 文章</span><h1>从源代码，到程序运行</h1><p>沿着前端、后端和运行时，阅读编译原理的完整脉络。</p><div class="article-library-meta"><span>${chapters.length} 篇文章</span><span>${pageCount} 页原图</span><span>${figureCount} 幅原图图表</span><a href="${href({view:'photos',domain:state.domain})}">${icon('photo')}原图资料</a></div></header><div class="article-search"><div class="search">${icon('search')}<input id="searchInput" type="search" aria-label="搜索文章正文" placeholder="搜索文章全文，如 SSA、闭包、垃圾收集…" value="${e(state.q)}" maxlength="180" autocomplete="off"><kbd>/</kbd></div><span role="status">${tokens.length?'找到 '+matches.length+' 篇相关文章':'按原图章节顺序阅读'}</span></div>${matches.length?groups.map((g,i)=>{const rows=matches.filter(a=>a.group===g);return rows.length?`<section class="article-group"><header><span>0${i+1}</span><h2>${g}</h2><p>${['理解语言与程序结构','生成并优化目标代码','让程序在机器上运行'][i]}</p></header><div class="article-cards">${rows.map(card).join('')}</div></section>`:'';}).join(''):`<div class="empty"><h2>没有找到相关文章</h2><p>试试“类型”“寄存器”或“虚拟机”。</p><button class="button" data-clear>清除搜索</button></div>`}<p class="article-library-note">按所提供图片转录正文，保留原文表述与历史语境；图表可点击核对原页。每篇文章均可下载 Markdown。</p>`;
  }
  const i=chapters.indexOf(current),neighbors=[chapters[i-1],chapters[i+1]];
  const toc=`<nav class="article-toc" aria-label="文章目录"><strong>本文目录</strong>${current.toc.map(t=>`<a class="toc-level-${t.level}" href="${route(current,t.id)}" data-section="${t.id}">${e(t.title)}</a>`).join('')}</nav>`;
  return `<div class="article-topline"><a href="${href({view:'articles',domain:current.domain})}">← 文章目录</a><span>${e(current.group)} · ${String(current.order).padStart(2,'0')} / ${String(chapters.length).padStart(2,'0')}</span></div><header class="article-heading"><span class="eyebrow">编译原理</span><h1>${e(current.title)}</h1><p>${e(current.summary)}</p><div class="article-actions"><span>原图 ${e(current.printedPages)} 页</span><a class="button" href="${e(current.markdown)}" download>${icon('download')}下载 Markdown</a><a class="button" href="${href({view:'photos',domain:current.domain})}">${icon('photo')}原图资料</a></div></header><details class="mobile-article-toc"><summary>本文目录 · ${current.toc.length} 个小节</summary>${toc}</details><div class="article-workspace"><article class="article-body" aria-label="${e(current.title)}正文">${current.html}<nav class="article-pagination" aria-label="上一篇和下一篇">${neighbors.map((a,j)=>a?`<a href="${route(a)}"><small>${j?'下一篇 →':'← 上一篇'}</small><strong>${e(a.title)}</strong></a>`:'<span></span>').join('')}</nav></article><aside class="desktop-article-toc">${toc}<a class="article-source-shortcut" href="photos/${e(current.primaryPhoto)}.jpg" data-photo="${e(current.primaryPhoto)}">${icon('photo')}对照章节原图</a></aside></div>`;
 }
 return {render};
};
